import { chromium } from 'playwright'

const BASE = process.env.PLAYWRIGHT_BASE_URL || 'http://127.0.0.1:8092'

async function run(w, h) {
  const browser = await chromium.launch()
  const page = await browser.newPage({ viewport: { width: w, height: h } })
  await page.goto(`${BASE}/index.html#/market-monitor`, { waitUntil: 'networkidle' })
  await page.waitForSelector('.mm-dashboard', { timeout: 20000 })
  await page.waitForTimeout(1200)

  const measure = async () => page.evaluate(() => {
    const charts = Array.from(document.querySelectorAll('.mm-chart')).map(el => Math.round(el.getBoundingClientRect().height))
    const main = document.querySelector('.mmd-main')
    const content = document.querySelector('.mmd-content')
    return {
      charts,
      mainScroll: main ? Math.round(main.scrollHeight) : null,
      mainClient: main ? Math.round(main.clientHeight) : null,
      contentH: content ? Math.round(content.getBoundingClientRect().height) : null,
      docH: Math.round(document.documentElement.scrollHeight),
      winH: window.innerHeight
    }
  })

  const t1 = await measure()
  await page.waitForTimeout(1500)
  const t2 = await measure()
  await page.waitForTimeout(1500)
  const t3 = await measure()

  console.log(`\n=== ${w}x${h} ===`)
  console.log('t1 charts:', t1.charts.join(','), 'contentH:', t1.contentH, 'mainScroll/client:', t1.mainScroll + '/' + t1.mainClient)
  console.log('t3 charts:', t3.charts.join(','), 'contentH:', t3.contentH)
  const maxDiff = Math.max(...t3.charts.map((v, i) => Math.abs(v - (t1.charts[i] ?? 0))))
  console.log('max chart height drift t1->t3:', maxDiff, '=>', maxDiff <= 2 ? 'STABLE ✅' : 'GROWING ❌')
  console.log('main internal scroll needed:', t3.mainScroll > t3.mainClient + 2 ? 'YES (scrolls) ✅' : 'NO')
  console.log('doc overflow (should be <=winH):', t3.docH, '<=', t3.winH, '=>', t3.docH <= t3.winH + 2 ? 'OK ✅' : 'OVERFLOW ❌')
  await browser.close()
}

await run(1920, 953)
await run(1920, 1080)
await run(1366, 768)

