import { chromium } from 'playwright'

const BASE = process.env.PLAYWRIGHT_BASE_URL || 'http://127.0.0.1:8092'

const browser = await chromium.launch()
const page = await browser.newPage({ viewport: { width: 1920, height: 953 } })
const fsCalls = []
page.on('console', m => { if (m.text().includes('FS')) console.log('console:', m.text()) })

await page.goto(`${BASE}/index.html#/market-monitor`, { waitUntil: 'networkidle' })
await page.waitForSelector('.mm-dashboard', { timeout: 20000 })
await page.waitForTimeout(800)

// 1) 旧的全屏按钮应消失，新的「返回首页」按钮应存在
